function tollSlide(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let best = Infinity;
  const walk = (r, c, paid, slideUsed) => {
    if (r === rows - 1 && c === cols - 1) {
      best = Math.min(best, paid);
      return;
    }
    if (r + 1 < rows) walk(r + 1, c, paid + grid[r + 1][c], slideUsed);
    if (c + 1 < cols) walk(r, c + 1, paid + grid[r][c + 1], slideUsed);
    if (!slideUsed) {
      for (let target = c + 1; target < cols; target++) walk(r, target, paid, true);
    }
  };
  walk(0, 0, grid[0][0], false);
  return best;
}

