function tollSlide(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const INF = 1e9;
  const plain = grid.map(() => new Array(cols).fill(INF));
  const slid = grid.map(() => new Array(cols).fill(INF));
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const toll = grid[r][c];
      if (r === 0 && c === 0) {
        plain[0][0] = toll;
        continue;
      }
      let p = INF;
      let s = INF;
      if (r > 0) {
        p = Math.min(p, plain[r - 1][c]);
        s = Math.min(s, slid[r - 1][c]);
      }
      if (c > 0) {
        p = Math.min(p, plain[r][c - 1]);
        s = Math.min(s, slid[r][c - 1]);
      }
      plain[r][c] = p + toll;
      slid[r][c] = s + toll;
      for (let from = 0; from < c; from++) slid[r][c] = Math.min(slid[r][c], plain[r][from]);
    }
  }
  return Math.min(plain[rows - 1][cols - 1], slid[rows - 1][cols - 1]);
}

function tollSlide(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const INF = 1e9;
  let plain = new Array(cols).fill(INF);
  let slid = new Array(cols).fill(INF);
  for (let r = 0; r < rows; r++) {
    const nextPlain = new Array(cols).fill(INF);
    const nextSlid = new Array(cols).fill(INF);
    let cheapestLeft = INF;
    for (let c = 0; c < cols; c++) {
      const toll = grid[r][c];
      if (r === 0 && c === 0) {
        nextPlain[0] = toll;
      } else {
        const fromAbove = r > 0 ? plain[c] : INF;
        const fromLeft = c > 0 ? nextPlain[c - 1] : INF;
        nextPlain[c] = Math.min(fromAbove, fromLeft) + toll;
        const slidAbove = r > 0 ? slid[c] : INF;
        const slidLeft = c > 0 ? nextSlid[c - 1] : INF;
        nextSlid[c] = Math.min(Math.min(slidAbove, slidLeft) + toll, cheapestLeft);
      }
      cheapestLeft = Math.min(cheapestLeft, nextPlain[c]);
    }
    plain = nextPlain;
    slid = nextSlid;
  }
  return Math.min(plain[cols - 1], slid[cols - 1]);
}
